def choose_move(observation):
    def gv(d, k, default=None):
        if isinstance(d, dict):
            return d.get(k, default)
        return default

    def to_xy(v):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        if isinstance(v, dict):
            if "x" in v and "y" in v:
                return v.get("x"), v.get("y")
            if "row" in v and "col" in v:
                return v.get("col"), v.get("row")
        return None

    def valid_xy(p):
        return isinstance(p, (list, tuple)) and len(p) >= 2 and isinstance(p[0], (int, float)) and isinstance(p[1], (int, float))

    def nearest(from_xy, points):
        if not valid_xy(from_xy):
            return None
        fx, fy = from_xy
        best = None
        best_d = None
        for p in points:
            if not valid_xy(p):
                continue
            px, py = p[0], p[1]
            d = abs(px - fx) + abs(py - fy)
            if best_d is None or d < best_d:
                best_d = d
                best = p
        return best

    def step_toward(src, dst):
        if not valid_xy(src) or not valid_xy(dst):
            return [0, 0]
        sx, sy = src
        dx = 0
        dy = 0
        if dst[0] > sx:
            dx = 1
        elif dst[0] < sx:
            dx = -1
        if dst[1] > sy:
            dy = 1
        elif dst[1] < sy:
            dy = -1
        return [dx, dy]

    def step_away(src, dst):
        if not valid_xy(src) or not valid_xy(dst):
            return [0, 0]
        sx, sy = src
        dx = 0
        dy = 0
        if dst[0] > sx:
            dx = -1
        elif dst[0] < sx:
            dx = 1
        if dst[1] > sy:
            dy = -1
        elif dst[1] < sy:
            dy = 1
        return [dx, dy]

    me = gv(observation, "agent")
    if me is None:
        me = gv(observation, "self")
    my_pos = to_xy(gv(me, "pos")) if me is not None else None
    if my_pos is None:
        my_pos = to_xy(gv(observation, "position"))
    if my_pos is None:
        my_pos = to_xy(gv(observation, "agent_pos"))

    # Gather candidate fields defensively
    resources = gv(observation, "resources", [])
    if not isinstance(resources, (list, tuple)):
        resources = []
    resource_points = []
    for r in resources:
        p = None
        if isinstance(r, dict):
            p = to_xy(gv(r, "pos"))
            if p is None:
                p = to_xy(r)
        else:
            p = to_xy(r)
        if valid_xy(p):
            resource_points.append(p)

    agents = gv(observation, "agents", [])
    if not isinstance(agents, (list, tuple)):
        agents = []
    others = []
    for a in agents:
        if a is me:
            continue
        p = None
        if isinstance(a, dict):
            p = to_xy(gv(a, "pos"))
            if p is None:
                p = to_xy(a)
        else:
            p = to_xy(a)
        if valid_xy(p):
            others.append(p)

    enemies = gv(observation, "enemies", [])
    if not isinstance(enemies, (list, tuple)):
        enemies = []
    enemy_points = []
    for e in enemies:
        p = None
        if isinstance(e, dict):
            p = to_xy(gv(e, "pos"))
            if p is None:
                p = to_xy(e)
        else:
            p = to_xy(e)
        if valid_xy(p):
            enemy_points.append(p)

    hazards = gv(observation, "hazards", [])
    if not isinstance(hazards, (list, tuple)):
        hazards = []
    hazard_points = []
    for h in hazards:
        p = None
        if isinstance(h, dict):
            p = to_xy(gv(h, "pos"))
            if p is None:
                p = to_xy(h)
        else:
            p = to_xy(h)
        if valid_xy(p):
            hazard_points.append(p)

    # Optional territory/target fields
    targets = []
    for key in ("target", "goal", "objective", "capture_point", "territories", "frontier"):
        v = gv(observation, key)
        if isinstance(v, (list, tuple)):
            for t in v:
                p = to_xy(t) if not isinstance(t, dict) else to_xy(gv(t, "pos")) or to_xy(t)
                if valid_xy(p):
                    targets.append(p)
        else:
            p = to_xy(v) if not isinstance(v, dict) else to_xy(gv(v, "pos")) or to_xy(v)
            if valid_xy(p):
                targets.append(p)

    # Prefer fleeing from nearby enemies/hazards if threatened
    threat_sources = []
    threat_sources.extend(enemy_points)
    threat_sources.extend(hazard_points)
    if threat_sources and valid_xy(my_pos):
        nearest_threat = nearest(my_pos, threat_sources)
        if nearest_threat is not None:
            # Flee only if close
            dist = abs(nearest_threat[0] - my_pos[0]) + abs(nearest_threat[1] - my_pos[1])
            if dist <= 3:
                move = step_away(my_pos, nearest_threat)
                if move != [0, 0]:
                    return move

    # Resource collection: go to nearest resource
    if resource_points and valid_xy(my_pos):
        target = nearest(my_pos, resource_points)
        if target is not None:
            return step_toward(my_pos, target)

    # Pursuit / territory: move toward nearest enemy or target
    if valid_xy(my_pos):
        if enemy_points:
            target = nearest(my_pos, enemy_points)
            if target is not None:
                return step_toward(my_pos, target)
        if targets:
            target = nearest(my_pos, targets)
            if target is not None:
                return step_toward(my_pos, target)

    # Mild center-seeking exploration if map info exists
    w = gv(observation, "width")
    h = gv(observation, "height")
    if valid_xy(my_pos) and isinstance(w, (int, float)) and isinstance(h, (int, float)) and w > 0 and h > 0:
