    H = observation.get("grid_height", 0)
    me = observation.get("self_position", (0, 0))
    opp = observation.get("opponent_position", (0, 0))
    res = observation.get("resources", [])
    obs = set(tuple(p) for p in observation.get("obstacles", []) if isinstance(p, (list, tuple)) and len(p) >= 2)
    sp = observation.get("self_path", [])
    op = observation.get("opponent_path", [])
    sx, sy = me[0], me[1]
    ox, oy = opp[0], opp[1]

    def ok(x, y):
        return 0 <= x < W and 0 <= y < H and (x, y) not in obs

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    targets = [tuple(p) for p in res if isinstance(p, (list, tuple)) and len(p) >= 2]
    if not targets:
        dx = 1 if ox > sx else -1 if ox < sx else 0
        dy = 1 if oy > sy else -1 if oy < sy else 0
        cand = [(dx, 0), (0, dy), (dx, dy), (0, 0)]
        for a, b in cand:
            nx, ny = sx + a, sy + b
            if ok(nx, ny):
                return [a, b]
        return [0, 0]

    best = None
    bestv = None
    for t in targets:
